'use strict';
// Operación independiente de Áurea. Las escrituras se validan y guardan en el servidor.
const extraUI={views:{},action:null,submit:null,decorate:null,modal:null};
const appState={user:null,csrf:null,initialized:false,data:null,revision:0,today:'',route:'inicio',tab:'',query:'',category:'Todos',cart:[],customerId:'',lastSaleId:null,payment:'cash',width:80,report:null,users:[],busy:false,start:'',end:'',offline:false};
const labels={inicio:'Inicio',pos:'Vender',ventas:'Ventas',inventario:'Inventario',metales:'Precios de metales',compras:'Compras',clientes:'Clientes y cartera',caja:'Caja y cuentas',reportes:'Reportes',usuarios:'Usuarios y permisos',ia:'Asistente IA',config:'Configuración',producto:'Producto',comprobante:'Comprobante',servicios:'Servicios de taller',activos:'Activos fijos'};
const permissionModule=r=>r==='documento'?(appState.documentPermission||'ventas'):({ajustes:'inventario',paneles:'inicio',producto:'inventario',comprobante:'ventas',servicios:'inventario',activos:'config',categorias:'inventario',gastos:'caja',medios:'config',perfiles:'usuarios',abonos:'clientes',abonoscompras:'compras',cartera:'clientes',creditos:'compras',reportescompras:'compras',informes:'reportes',documento:'ventas'}[r]||r);
const isSuper=()=>appState.user?.role==='Superadministrador';
const accessModules=["inicio","pos","ventas","inventario","metales","compras","clientes","caja","reportes","usuarios","ia","config","proveedores","servicios","categorias","activos","perfiles","gastos","medios","cartera","creditos","abonos","abonoscompras","cierres","reportescompras","radar","tendencia","periodos","balance","margen","finanzas","general","ranking"];
const accessParents={"proveedores":"compras","servicios":"inventario","categorias":"inventario","activos":"config","perfiles":"usuarios","gastos":"caja","medios":"config","cartera":"clientes","creditos":"compras","abonos":"clientes","abonoscompras":"compras","cierres":"caja","reportescompras":"compras","radar":"reportes","tendencia":"reportes","periodos":"reportes","balance":"reportes","margen":"reportes","finanzas":"reportes","general":"reportes","ranking":"reportes"};
let sidebarCollapsed=false;
try{sidebarCollapsed=localStorage.getItem('aurea-sidebar-collapsed')==='1';}catch{}
const sidebarDesktop=window.matchMedia('(min-width:1024px)');
function syncSidebar(){const shell=document.querySelector('.app-shell'),side=document.querySelector('.sidebar'),toggle=document.querySelector('[data-action="menu"].sidebar-toggle');if(!side||!shell||!toggle)return;const expanded=sidebarDesktop.matches?!sidebarCollapsed:side.classList.contains('open');shell.classList.toggle('sidebar-collapsed',sidebarCollapsed);shell.classList.toggle('sidebar-mobile-open',!sidebarDesktop.matches&&expanded);side.inert=!expanded;toggle.setAttribute('aria-expanded',String(expanded));toggle.setAttribute('aria-label',expanded?'Ocultar menú lateral':'Mostrar menú lateral');toggle.title=expanded?'Ocultar menú lateral':'Mostrar menú lateral';}
function toggleSidebar(force){const side=document.querySelector('.sidebar');if(!side)return;if(sidebarDesktop.matches){sidebarCollapsed=typeof force==='boolean'?!force:!sidebarCollapsed;try{localStorage.setItem('aurea-sidebar-collapsed',sidebarCollapsed?'1':'0');}catch{}}else side.classList.toggle('open',typeof force==='boolean'?force:!side.classList.contains('open'));if(side.inert&&side.contains(document.activeElement))document.querySelector('.sidebar-toggle')?.focus();syncSidebar();if(side.inert&&side.contains(document.activeElement))document.querySelector('.sidebar-toggle')?.focus();}
sidebarDesktop.addEventListener('change',()=>{document.querySelector('.sidebar')?.classList.remove('open');syncSidebar();});
const allowed=(m,a='ver')=>['utilidad','importar'].includes(m)?isSuper():['Administrador','Superadministrador'].includes(appState.user?.role)||(appState.user?.permissions?.[m]??appState.user?.permissions?.[accessParents[m]||permissionModule(m)]??[]).includes(a);
const data=()=>appState.data;
const activeShift=()=>data()?.shifts.find(s=>!s.closedAt);
const paid=o=>(o.payments||[]).filter(p=>!p.voidedAt).reduce((n,p)=>n+p.amount,0);
const balance=o=>o.voidedAt||o.legacyDebtConsolidated?0:o.total-paid(o)-(o.writeoff||0);
const fmtDate=v=>v?new Date(v.length===10?v+'T12:00:00-05:00':v).toLocaleDateString('es-CO',{timeZone:'America/Bogota',day:'2-digit',month:'short',year:'numeric'}):'—';
const fmtTime=v=>new Date(v).toLocaleTimeString('es-CO',{timeZone:'America/Bogota',hour:'2-digit',minute:'2-digit'});
const expected=shift=>shift?shift.opening+data().movements.filter(m=>m.shiftId===shift.id&&m.accountId==='cash').reduce((n,m)=>n+m.amount,0):0;
const bank=a=>a.opening+data().movements.filter(m=>m.accountId===a.id).reduce((n,m)=>n+m.amount,0);
const countLabel=(p,n=p.stock)=>p.measureType==='Pesaje'?grams(n):n+' un.';
const button=(label,action,kind='',ic='')=>`<button class="btn ${kind}" data-action="${esc(action)}">${ic?icon(ic,16):''}${esc(label)}</button>`;
const badge=(label,kind='')=>`<span class="badge ${kind}">${icon(kind==='red'?'alert':kind==='warn'?'clock':'check',11)}${esc(label)}</span>`;
const empty=(title,message,action='')=>`<section class="empty">${icon('diamond',35)}<h2>${esc(title)}</h2><p>${esc(message)}</p>${action}</section>`;
const heading=(title,subtitle,actions='')=>`<div class="page-heading"><div><div class="eyebrow">Áurea / ${esc(labels[appState.route]||'Tu negocio')}</div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div><div class="actions">${actions}</div></div>`;
const kpi=(title,value,foot='',primary=false)=>`<article class="card kpi ${primary?'emphasis':''}"><div class="kpi-title">${esc(title)}</div><div class="kpi-value ${/[a-záéíóúñ]/i.test(String(value))&&String(value).length>16?'is-message':''}">${esc(value)}</div><div class="kpi-foot">${esc(foot)}</div></article>`;
const table=(headers,rows)=>rows.length?`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th class="${/Total|Saldo|Precio|Costo|Valor|Peso|Monto/.test(h)?'num':''}">${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`:empty('Sin registros para mostrar','Prueba otra búsqueda o registra la primera operación.');
const tabs=items=>`<div class="tabs">${items.map(([id,label],i)=>`<button class="tab ${appState.tab===id||!appState.tab&&!i?'active':''}" data-tab="${id}">${label}</button>`).join('')}</div>`;
const search=(placeholder,actions='')=>`<div class="filters"><label class="search">${icon('search',16)}<input id="search" type="search" value="${esc(appState.query)}" placeholder="${esc(placeholder)}" aria-label="${esc(placeholder)}"></label>${actions}</div>`;
const input=(label,name,value='',type='text',attrs='')=>`<label class="field"><span>${label}</span><input class="input" name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
const select=(label,name,options,value='')=>`<label class="field"><span>${label}</span><select name="${name}">${options.map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`;}).join('')}</select></label>`;
const errorBox=()=>'<p class="field-error form-error" role="alert"></p>';
const submit=label=>errorBox()+`<button class="btn primary full large" type="submit">${esc(label)}</button>`;
let toastTimer;
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),5500);}
async function api(url,options={}){let response;try{response=await fetch(url,{credentials:'same-origin',...options,headers:{...(options.body?{'Content-Type':'application/json','X-CSRF-Token':appState.csrf||''}:{}),...options.headers},signal:AbortSignal.timeout(30000)});}catch{appState.offline=true;throw Error('No hay conexión con Áurea. Tu formulario se conserva; verifica el resultado antes de repetir una operación.');}const body=await response.json();if(!response.ok){const e=Error(body.error||'No se pudo completar la operación.');e.status=response.status;throw e;}appState.offline=false;return body;}
async function load(){const result=await api('/api/state');appState.data=result.data;if(result.user)appState.user=result.user;appState.revision=result.revision;appState.today=result.today;if(!appState.start)appState.start=result.today;if(!appState.end)appState.end=result.today;if(allowed('usuarios')||allowed('perfiles'))appState.users=(await api('/api/users')).users;}
async function mutate(command,body,form){const serialized=JSON.stringify({command,body});if(!form._request||form._request.body!==serialized)form._request={body:serialized,key:crypto.randomUUID(),revision:appState.revision};const result=await api('/api/command',{method:'POST',headers:{'Idempotency-Key':form._request.key},body:JSON.stringify({command,body,revision:form._request.revision})});await load();form._request=null;return result;}
function go(route){if(location.hash==='#'+route){appState.route=route;appState.tab='';appState.query='';render();}else location.hash=route;}
function modal(title,body,footer=''){const d=document.querySelector('#dialog');d.innerHTML=`<div class="modal-head"><h2 id="dialog-title">${esc(title)}</h2><button class="icon-btn" data-action="close-dialog" aria-label="Cerrar diálogo">${icon('close')}</button></div><div class="modal-body">${body}</div>${footer?'<div class="modal-foot">'+footer+'</div>':''}`;if(!d.open)d.showModal();extraUI.modal?.();}
function closeModal(){document.querySelector('#dialog').close();}
function brand(){return `<div class="brand"><span class="brand-mark">${icon('diamond',23)}</span>áurea</div>`;}
function shell(){const list=[['inicio','home'],['pos','plus'],['ventas','receipt'],['inventario','box'],['compras','bag'],['clientes','users'],['caja','wallet'],['reportes','chart'],['ia','spark'],['usuarios','users'],['config','settings']];const active={producto:'inventario',metales:'inventario',servicios:'inventario',comprobante:'ventas',activos:'config',categorias:'inventario',gastos:'caja',medios:'config',perfiles:'usuarios',abonos:'clientes',abonoscompras:'compras',cartera:'clientes',creditos:'compras',reportescompras:'compras',informes:'reportes'}[appState.route]||appState.route;return `<div class="app-shell"><aside class="sidebar" id="sidebar" aria-label="Navegación principal">${brand()}<div class="brand-caption">${esc(data().settings.slogan||'Gestión que brilla')}</div><nav>${list.filter(([r])=>allowed(r)).map(([r,i])=>`<a href="#${r}" class="nav-item ${active===r?'active':''} ${r==='pos'?'pos':''}" ${active===r?'aria-current="page"':''}>${icon(i)}${r==='pos'?'Nueva venta':labels[r]}</a>`).join('')}</nav><div class="sidebar-footer"><div class="prototype-badge"><span class="dot"></span>${esc(data().settings.name)}</div><small style="display:block;margin-top:8px;font-size:10px">${appState.offline?'Sin conexión':'Datos guardados localmente'}</small></div></aside><button class="sidebar-backdrop" data-action="menu" aria-label="Cerrar menú lateral" tabindex="-1"></button><div class="workspace"><header class="topbar"><button class="icon-btn sidebar-toggle" data-action="menu" aria-controls="sidebar" aria-expanded="true" aria-label="Ocultar menú lateral">${icon('menu')}</button><span class="crumb">Tu negocio <span style="margin:0 10px">/</span> ${esc(labels[appState.route]||'Inicio')}</span><div class="top-actions">${allowed('caja')?`<button class="turn" data-action="goto-caja">${icon(activeShift()?'check':'lock',12)}Caja ${activeShift()?'abierta':'cerrada'}</button>`:''}${allowed('metales')||allowed('pos')?`<button class="metal-top" style="background:none;border:0;border-left:1px solid var(--border);text-align:left" data-action="${allowed('metales')?'goto-metales':'none'}"><span class="muted">Oro 18k · tarifa comercial</span><br><strong>${money(data().metals[0].rate)} / g</strong></button>`:''}<button class="icon-btn" data-action="notifications" aria-label="Ver notificaciones">${icon('bell')}</button><button class="user" data-action="account"><span class="avatar">${esc(appState.user.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span><span class="user-label"><strong style="font-size:11px">${esc(appState.user.name)}</strong><small>${esc(appState.user.role)}</small></span>${icon('down',12)}</button></div></header><main class="main ${appState.route==='pos'?'pos-page':''}" id="main" tabindex="-1"></main></div></div>`;}
function authView(){const setup=!appState.initialized;document.querySelector('#app').innerHTML=`<main class="login" id="main"><section class="login-story">${brand()}<h1>El valor de tu negocio,<br>en cada detalle.</h1><p>Un espacio para cuidar tus piezas, tus clientes y todo lo que has construido.</p><div class="login-art">${icon('diamond',180)}</div><small style="color:#c2d4c8">ÁUREA · GESTIÓN PARA JOYERÍAS</small></section><section class="login-form-area"><form class="login-form" id="${setup?'setup-form':'login-form'}"><div class="eyebrow">${setup?'TU NUEVO COMIENZO':'TU JOYERÍA, CONECTADA'}</div><h2>${setup?'Hagamos espacio para tu negocio.':'Bienvenida de nuevo.'}</h2><p>${setup?'Crea tu administrador. Esta instalación tiene su propia base de datos y empieza vacía.':'Ingresa a tu espacio de trabajo.'}</p>${setup?input('Nombre de la joyería','storeName','Áurea','text','required maxlength="80"')+input('Tu nombre','name','','text','required maxlength="100"'):''}${input('Correo electrónico','email','','email','required autocomplete="username"')}${input('Contraseña','password','','password',`required ${setup?'minlength="12" autocomplete="new-password"':'autocomplete="current-password"'}`)}${setup?input('Código de instalación (solo si lo configuraste)','setupToken','','password','autocomplete="off"'):''}${submit(setup?'Crear mi espacio de trabajo':'Iniciar sesión')}<div class="login-demo">${icon('lock',13)}${setup?'Usa una contraseña de al menos 12 caracteres. No se importan datos ni accesos de otros sistemas.':'Tu sesión dura hasta ocho horas. Los permisos se validan en el servidor.'}</div></form></section></main>`;}
function reportLocal(start=appState.today,end=appState.today){const recognized=data().sales.filter(x=>!x.voidedAt&&x.recognizedAt&&new Date(x.recognizedAt).toLocaleDateString('en-CA',{timeZone:'America/Bogota'})>=start&&new Date(x.recognizedAt).toLocaleDateString('en-CA',{timeZone:'America/Bogota'})<=end);const net=recognized.reduce((n,s)=>n+(s.total-(s.tax||0)),0),cost=recognized.reduce((n,s)=>n+(s.cost||0),0),expenses=data().movements.filter(m=>m.kind==='expense'&&m.date>=start&&m.date<=end).reduce((n,m)=>n-m.amount,0);const missingCosts=recognized.some(s=>s.costUnknown);return {net,cost:missingCosts?null:cost,gross:missingCosts?null:net-cost,expenses,profit:missingCosts?null:net-cost-expenses,count:recognized.length};}
function home(){const r=reportLocal(),debt=data().sales.filter(s=>s.mode==='credit').reduce((n,s)=>n+balance(s),0);const low=data().products.filter(p=>p.active&&p.stock<=p.minStock);return heading('Cada detalle cuenta.',new Date().toLocaleDateString('es-CO',{timeZone:'America/Bogota',weekday:'long',day:'numeric',month:'long',year:'numeric'})+' · Así va tu joyería hoy.',allowed('pos','crear')?button('Nueva venta','goto-pos','primary','plus'):'')+`<div class="kpis">${kpi('Ventas reconocidas hoy',money(r.net),r.count+' ventas',true)}${isSuper()?kpi('Utilidad bruta',money(r.gross),'Con el costo guardado al vender'):kpi('Transacciones',r.count,'Ventas reconocidas hoy')}${kpi('Efectivo del turno',money(expected(activeShift())),activeShift()?'Caja abierta':'Caja cerrada')}${kpi('Cartera de crédito',money(debt),'Abonos no se cuentan como ventas')}</div><div class="grid-two"><section class="card"><div class="card-head"><h2>El pulso de tus ventas</h2><small>Últimos 7 días</small></div>${salesChart()}</section><section class="card"><div class="card-head"><h2>Requieren tu atención</h2></div><div class="list-item"><div class="list-icon">${icon('box')}</div><div class="list-text"><p>${low.length} referencias con stock bajo</p><small>Revisa mínimos y existencias.</small></div>${allowed('inventario')?button('Ver','goto-inventario','text'):''}</div><div class="list-item"><div class="list-icon violet">${icon('users')}</div><div class="list-text"><p>${money(debt)} en crédito pendiente</p><small>Consulta vencimientos por venta.</small></div>${allowed('clientes')?button('Ver','goto-clientes','text'):''}</div><div class="list-item"><div class="list-icon red">${icon('bag')}</div><div class="list-text"><p>${money(data().purchases.reduce((n,p)=>n+balance(p),0))} por pagar</p><small>Las compras no son gastos operativos.</small></div></div></section></div><section class="card"><div class="card-head"><h2>Últimas ventas</h2>${allowed('ventas')?button('Ver todas','goto-ventas','text','arrow'):''}</div>${salesTable(data().sales.slice(0,8))}</section>`;}
function salesChart(){const points=[];for(let i=6;i>=0;i--){const day=new Date(appState.today+'T12:00:00-05:00');day.setUTCDate(day.getUTCDate()-i);const date=day.toLocaleDateString('en-CA',{timeZone:'America/Bogota'});const total=reportLocal(date,date).net;points.push({date,total});}const max=Math.max(...points.map(p=>p.total),1);return `<div class="card-body report-chart" role="img" aria-label="Ventas reconocidas por día: ${points.map(p=>fmtDate(p.date)+' '+money(p.total)).join('; ')}">${points.map(p=>`<div class="report-bar" style="height:${Math.max(2,p.total/max*90)}%" title="${fmtDate(p.date)}: ${money(p.total)}"><span>${p.date.slice(8)}</span></div>`).join('')}</div><p class="chart-note">Ventas reconocidas en COP. Los planes separe se reconocen al entregar.</p>`;}
function saleStatus(s){return s.voidedAt?badge('Anulada','red'):s.legacyDebtConsolidated&&['credit','layaway'].includes(s.mode)?badge('Saldo consolidado','info'):s.mode==='layaway'&&!s.recognizedAt?badge(balance(s)?'Separado · saldo pendiente':'Listo para entregar','info'):balance(s)?badge(s.dueDate<appState.today?'Vencido':'Saldo pendiente',s.dueDate<appState.today?'red':'violet'):badge('Pagado');}
function salesTable(list){return table(['Venta / Fecha','Cliente','Tipo','Estado','Total','Saldo',''],list.map(s=>`<tr><td><strong>${esc(s.id)}</strong><small>${fmtDate(s.createdAt)} · ${fmtTime(s.createdAt)}</small></td><td>${esc(s.customer)}<small>${s.items.length} referencias · ${esc(s.cashier)}</small></td><td>${{paid:'Contado',credit:'Crédito',layaway:'Plan separe'}[s.mode]}</td><td>${saleStatus(s)}</td><td class="num">${money(s.total)}</td><td class="num">${money(balance(s))}</td><td>${allowed('ventas')?button('Detalle','sale-'+s.id,'text'):''}</td></tr>`));}
function salesView(){return heading('Cada venta tiene una historia.','Consulta comprobantes, abonos, entregas y anulaciones.',allowed('pos','crear')?button('Nueva venta','goto-pos','primary','plus'):'')+`<section class="card">${search('Buscar venta, cliente o fecha',exportButtons('ventas'))}<div id="results">${salesTable(filtered(data().sales,s=>s.id+' '+s.customer+' '+s.date))}</div></section>`;}
const filtered=(list,fn)=>list.filter(x=>fn(x).toLowerCase().includes(appState.query.toLowerCase()));
function productsView(){const products=data().products.filter(p=>p.active);return heading('Cada pieza, en su lugar.','Existencias, gramos, costo y precio comercial de tu colección.',`${allowed('metales')?button('Metales','goto-metales','','diamond'):''}${button('Servicios','goto-servicios')}${allowed('inventario','crear')?button('Nuevo producto','product-new','primary','plus'):''}`)+`<div class="kpis">${kpi('Referencias activas',products.length)}${kpi('Peso disponible',grams(products.reduce((n,p)=>n+(p.measureType==='Pesaje'?p.stock:p.stock*p.weight),0)))}${kpi('Valor al costo',money(products.reduce((n,p)=>n+p.stock*p.cost,0)))}${kpi('Con stock bajo',products.filter(p=>p.stock<=p.minStock).length)}</div><section class="card">${search('Buscar por nombre, referencia o metal',exportButtons('inventario'))}<div id="results">${productRows()}</div></section>`;}
function productRows(){return table(['Referencia / Producto','Medida','Peso por pieza','Existencias','Precio',''],filtered(data().products.filter(p=>p.active),p=>p.name+' '+p.sku+' '+(p.barcode||'')+' '+p.metal+' '+p.category).map(p=>`<tr><td><strong>${esc(p.name)}</strong><small>${esc(p.sku)} · ${esc(p.metal)}</small></td><td>${p.measureType==='Pesaje'?'Gramos':'Unidades'}</td><td class="num">${p.measureType==='Pesaje'?'—':grams(p.weight)}</td><td>${countLabel(p)} ${p.stock<=p.minStock?badge('Stock bajo','warn'):''}</td><td class="num">${money(p.price)} / ${p.measureType==='Pesaje'?'g':'un.'}</td><td>${button('Ver detalle','product-'+p.id,'text')}</td></tr>`));}
let selectedProductId=null;
function productView(){const p=data().products.find(p=>p.id===selectedProductId);if(!p)return empty('Selecciona una pieza','Abre la referencia desde Inventario.',button('Ver inventario','goto-inventario','primary'));return heading(p.name,p.sku+' · '+p.category,button('Volver','goto-inventario','','back')+(allowed('inventario','editar')?button('Editar producto','product-edit-'+p.id,'primary','edit'):''))+`<section class="card"><div class="card-body detail-grid">${jewel({...p,type:p.category==='Cadenas'?'chain':p.category==='Aretes'?'earrings':'ring'})}<div><h2>${esc(p.name)}</h2><div class="specs">${[['Metal',p.metal],['Existencias',countLabel(p)],['Peso por unidad',grams(p.weight)],['Costo por '+(p.measureType==='Pesaje'?'g':'unidad'),money(p.cost)],['Precio comercial',money(p.price)],['Stock mínimo',countLabel(p,p.minStock)]].map(([l,v])=>`<div><small>${esc(l)}</small><strong>${esc(v)}</strong></div>`).join('')}</div><p class="muted">${p.pricing==='metal'?'Precio calculado con la tarifa del metal y la mano de obra. ':''}El costo se guarda en cada venta para conservar la utilidad histórica.</p><div class="row" style="margin-top:20px">${allowed('inventario','editar')?button('Ajustar existencias','stock-'+p.id,'','edit'):''}${allowed('inventario','eliminar')?button('Desactivar','archive-'+p.id,'','close'):''}</div></div></div></section>`;}
function pos(){return heading('Una nueva pieza. Una nueva historia.','Precios comerciales por unidad o gramo · Revisa el total antes de cobrar.')+(!activeShift()?`<div class="info-strip">${icon('lock')}La caja está cerrada. Abre un turno antes de registrar la venta. ${allowed('caja')?button('Abrir caja','goto-caja','text'):''}</div>`:'')+`<div class="pos-layout"><section><label class="search">${icon('search')}<input id="pos-search" placeholder="Buscar pieza, referencia o escanear código…" aria-label="Buscar producto"></label><div class="chips">${['Todos',...data().categories].map(c=>`<button class="chip ${appState.category===c?'active':''}" data-category="${esc(c)}">${esc(c)}</button>`).join('')}</div><div class="pos-catalog" id="catalog">${catalog()}</div></section><aside class="card cart" id="cart" aria-label="Carrito de venta">${cartView()}</aside></div><button class="btn primary large pos-cart-shortcut" data-action="scroll-cart">Ver carrito · ${money(cartTotal())}</button>`;}
function catalog(query=''){const list=data().products.filter(p=>p.active&&(appState.category==='Todos'||p.category===appState.category)&&[p.name,p.sku,p.barcode,p.metal,p.category,data().suppliers.find(s=>s.id===p.supplierId)?.name].join(' ').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(query.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()));return list.length?list.map(p=>`<button class="product" data-add="${p.id}" ${p.stock<=0||(!p.price&&!allowed('pos','editar')&&!allowed('inventario','editar'))?'disabled':''} aria-label="Agregar ${esc(p.name)} al carrito">${jewel({...p,type:p.category==='Cadenas'?'chain':p.category==='Aretes'?'earrings':'ring'})}<div class="product-info"><h3>${esc(p.name)}</h3><small>${esc(p.sku)} · ${p.measureType==='Pesaje'?'Venta por gramo':grams(p.weight)+'/un.'}</small><strong>${money(p.price)} / ${p.measureType==='Pesaje'?'g':'un.'}</strong><span class="stock">${p.stock<=0?'Agotado':!p.price?'Define el precio de venta':countLabel(p)+' disponibles'}</span></div></button>`).join(''):empty('Tu colección empieza aquí.','Registra las piezas en Inventario para comenzar a vender.',allowed('inventario','crear')?button('Registrar producto','product-new','primary','plus'):'');}
const cartSubtotal=()=>appState.cart.reduce((n,i)=>n+Math.round(i.qty*i.unitPrice)-i.discount,0);
const cartTotal=()=>{const subtotal=cartSubtotal();return subtotal+Math.round(subtotal*Number(data()?.settings.taxRate||0)/100);};
function cartView(){return `<div class="card-head"><h2>Tu venta <small>(${appState.cart.length})</small></h2><small>COP</small></div><div class="cart-customer">${select('Cliente','cart-customer',[['','Cliente de mostrador'],...data().customers.filter(c=>c.active!==false).map(c=>[c.id,c.name])],appState.customerId)}</div>${appState.cart.length?appState.cart.map((i,index)=>{const p=data().products.find(p=>p.id===i.productId);return `<div class="cart-item"><div class="row between"><h3>${esc(p.name)}</h3><button class="icon-btn" data-remove="${index}" aria-label="Quitar ${esc(p.name)}">${icon('close',15)}</button></div><small>${esc(p.metal)} · ${p.measureType==='Pesaje'?'Cantidad en gramos':grams(p.weight)+'/un.'}</small><div class="row between"><label class="field" style="margin:12px 0 0"><span>${p.measureType==='Pesaje'?'Gramos':'Cantidad'}</span><input class="input" type="number" min="${p.measureType==='Pesaje'?'.000001':'1'}" max="${p.stock}" step="${p.measureType==='Pesaje'?'.001':'1'}" value="${i.qty}" data-cart-qty="${index}" aria-label="Cantidad de ${esc(p.name)}"></label><strong>${money(Math.round(i.qty*i.unitPrice)-i.discount)}</strong></div>${(allowed('inventario','editar')||allowed('pos','editar'))?`<label style="display:block;margin-top:12px;font-size:11px">Precio manual COP / ${p.measureType==='Pesaje'?'g':'un.'}<input class="input" type="number" min=".000001" step=".000001" value="${i.unitPrice}" data-unit-price="${index}" aria-label="Precio de ${esc(p.name)}" style="width:100%;margin-top:6px"></label>`:''}${(allowed('ventas','editar')||allowed('pos','editar'))?`<div class="row" style="margin-top:12px"><label style="font-size:11px">Descuento COP <input class="input" type="number" min="0" step="1" value="${i.discount}" data-discount="${index}" aria-label="Descuento de ${esc(p.name)}" style="width:110px"></label></div>`:''}</div>`;}).join(''):empty('Tu próxima venta empieza aquí','Selecciona una pieza del catálogo.')}<div class="cart-summary"><div class="total-line"><span>Peso total</span><span>${grams(appState.cart.reduce((n,i)=>{const p=data().products.find(p=>p.id===i.productId);return n+i.qty*(p.measureType==='Pesaje'?1:p.weight);},0))}</span></div><div class="total-line grand"><span>Total</span><span>${money(cartTotal())}</span></div><button class="btn primary large full" data-action="checkout" ${!appState.cart.length||cartTotal()<=0?'disabled':''}>Continuar al pago ${icon('arrow',16)}</button><small style="display:block;margin-top:12px;text-align:center">${appState.offline?'Sin conexión: quedará pendiente, sin confirmar el cobro.':'El registro confirma una operación real en Áurea.'}</small></div>`;}
function productForm(id){const p=id?data().products.find(p=>p.id===id):null;modal(p?'Editar producto':'Registrar producto',`<form id="product-form" data-id="${p?.id||''}"><div class="form-grid">${input('Nombre de la pieza','name',p?.name||'','text','required maxlength="180"')}${input('Referencia única / SKU','sku',p?.sku||'','text','required maxlength="70"')}${select('Categoría','category',data().categories,p?.category||'Anillos')}${select('Metal / ley','metal',data().metals.map(m=>m.name).concat('Sin metal'),p?.metal||'Oro 18k')}${select('Unidad de venta y existencia','measureType',['Unidades','Pesaje'],p?.measureType||'Unidades')}${input('Peso por pieza (g; 0 si no aplica)','weight',p?.weight||0,'number','required min="0" step=".000001"')}${input('Existencias iniciales (un. o g)','stock',p?.stock||0,'number',`required min="0" step=".001" ${p?'readonly':''}`)}${input('Mínimo de stock (un. o g)','minStock',p?.minStock??1,'number','required min="0" step=".001"')}${input('Costo por unidad de venta (COP)','cost',p?.cost||0,'number','required min="0" step="1"')}${select('Cálculo de precio','pricing',[['fixed','Precio fijo'],['metal','Tarifa del metal × peso + mano de obra']],p?.pricing||'fixed')}${input('Mano de obra (COP/unidad de venta)','labor',p?.labor||0,'number','required min="0" step="1"')}${input('Precio fijo (COP; 0 si se calcula por metal)','price',p?.price||0,'number','required min="0" step="1"')}</div><div class="info-strip">Para venta por gramo, stock y cantidad están en gramos; costo y precio son por gramo. Para venta por unidad, el peso es informativo. El costo se fija al registrar cada venta.</div>${submit('Guardar producto')}</form>`);}
function metalView(){return heading('La precisión empieza en el precio.','Tarifas comerciales manuales. Cambiarlas no modifica ventas ni precios ya fijados.')+`<div class="metals-grid">${data().metals.map(m=>`<article class="card metal-card"><div class="metal-swatch"></div><h2>${esc(m.name)}</h2><div class="metal-price">${money(m.rate)} <small>/ g</small></div><small>${m.updatedAt?'Actualizada '+fmtDate(m.updatedAt):'Tarifa inicial · revisa antes de usar'}</small><div style="margin-top:20px">${allowed('metales','editar')?button('Actualizar tarifa','metal-'+m.id,'','edit'):''}</div></article>`).join('')}</div><section class="card"><div class="card-head"><h2>Historial de tarifas</h2></div>${table(['Metal','Anterior','Nueva tarifa','Responsable','Fecha'],data().metalHistory.map(m=>`<tr><td>${esc(m.metal)}</td><td>${money(m.old)}</td><td>${money(m.rate)}</td><td>${esc(m.userName)}</td><td>${fmtDate(m.createdAt)}</td></tr>`))}</section>`;}
function contactForm(kind,id){const c=id?(kind==='supplier'?data().suppliers:data().customers).find(c=>c.id===id):null;modal((c?'Editar ':'Registrar ')+(kind==='supplier'?'proveedor':'cliente'),`<form id="contact-form" data-kind="${kind}" data-id="${c?.id||''}">${input('Nombre completo / razón social','name',c?.name||'','text','required')}${input('Documento / NIT','doc',c?.doc||'','text','required')}${input('Teléfono','phone',c?.phone||'','tel')}${input('Correo','email',c?.email||'','email')}${input('Dirección','address',c?.address||'')}${kind==='customer'?input('Cupo de crédito (COP; requiere autorización)','creditLimit',c?.creditLimit||0,'number','required min="0" step="1" '+(allowed('clientes','editar')?'':'readonly')):''}${submit('Guardar '+(kind==='supplier'?'proveedor':'cliente'))}</form>`);}
function clientView(){const sum=data().sales.filter(s=>s.mode==='credit').reduce((n,s)=>n+balance(s),0);return heading('Relaciones que valen oro.','Clientes, saldos por operación y abonos con trazabilidad.',allowed('clientes','crear')?button('Nuevo cliente','customer-new','primary','plus'):'')+`<div class="kpis">${kpi('Clientes',data().customers.length)}${kpi('Cartera de crédito',money(sum))}${kpi('Saldo de separes',money(data().sales.filter(s=>s.mode==='layaway'&&!s.recognizedAt).reduce((n,s)=>n+balance(s),0)),'No es cuenta por cobrar contable')}${kpi('Operaciones vencidas',data().sales.filter(s=>balance(s)>0&&s.dueDate<appState.today).length)}</div><section class="card">${search('Buscar cliente o documento')}<div id="results">${customerRows()}</div></section>`;}
function customerRows(){return table(['Cliente / Documento','Contacto','Crédito pendiente','Separes pendientes',''],filtered(data().customers.filter(c=>appState.includeInactive||c.active!==false),c=>c.name+' '+c.doc+' '+c.phone).map(c=>`<tr><td><strong>${esc(c.name)}</strong><small>${esc(c.doc)}</small></td><td>${esc(c.phone||'—')}</td><td class="num">${money(data().sales.filter(s=>s.customerId===c.id&&s.mode==='credit').reduce((n,s)=>n+balance(s),0))}</td><td class="num">${money(data().sales.filter(s=>s.customerId===c.id&&s.mode==='layaway'&&!s.recognizedAt).reduce((n,s)=>n+balance(s),0))}</td><td>${button('Ver ficha','customer-'+c.id,'text')}</td></tr>`));}
function customerDetail(id){const c=data().customers.find(c=>c.id===id);const list=data().sales.filter(s=>s.customerId===id);modal(c.name,`<div class="row between"><span>${esc(c.doc)}</span><strong>Cupo: ${money(c.creditLimit)}</strong></div><p style="margin:14px 0">${esc(c.phone||'Sin teléfono')} · ${esc(c.email||'Sin correo')}</p><h3 style="margin:20px 0">Compras, créditos y planes separe</h3>${table(['Operación','Total','Saldo','Estado',''],list.map(s=>`<tr><td>${s.id}<small>${fmtDate(s.createdAt)}</small></td><td class="num">${money(s.total)}</td><td class="num">${money(balance(s))}</td><td>${saleStatus(s)}</td><td>${balance(s)>0&&allowed('clientes','crear')?button('Abonar','sale-payment-'+s.id,'text'):button('Detalle','sale-'+s.id,'text')}</td></tr>`))}`,allowed('clientes','editar')?button('Editar cliente','customer-edit-'+id,'','edit'):'');}
function purchasesView(){return heading('Tu abastecimiento, sin puntos ciegos.','Recibe mercancía y registra sus pagos sin duplicar gastos.',allowed('compras','crear')?button('Registrar compra','purchase-new','primary','plus'):'')+tabs([['ingresos','Ingresos de mercancía'],['proveedores','Proveedores'],['pendientes','Cuentas por pagar']])+`<div class="kpis">${kpi('Ingresos registrados',data().purchases.length)}${kpi('Total comprado',money(data().purchases.reduce((n,p)=>n+p.total,0)))}${kpi('Saldo por pagar',money(data().purchases.reduce((n,p)=>n+balance(p),0)))}${kpi('Proveedores',data().suppliers.length)}</div><section class="card">${search(appState.tab==='proveedores'?'Buscar proveedor':'Buscar compra o proveedor',appState.tab==='proveedores'&&allowed('compras','crear')?button('Nuevo proveedor','supplier-new','','plus'):exportButtons('compras'))}<div id="results">${purchaseRows()}</div></section>`;}
function purchaseRows(){if(appState.tab==='proveedores')return table(['Proveedor / Documento','Contacto','Saldo',''],filtered(data().suppliers.filter(s=>appState.includeInactive||s.active!==false),s=>s.name+' '+s.doc).map(s=>`<tr><td><strong>${esc(s.name)}</strong><small>${esc(s.doc)}</small></td><td>${esc(s.phone||'—')}</td><td class="num">${money(data().purchases.filter(p=>p.supplierId===s.id).reduce((n,p)=>n+balance(p),0))}</td><td>${button('Estado de cuenta','supplier-'+s.id,'text')}${allowed('compras','editar')?button('Editar','supplier-edit-'+s.id,'text'):''}</td></tr>`));return table(['Orden / Factura','Proveedor','Mercancía','Total','Saldo','Vence',''],filtered(data().purchases.filter(p=>appState.tab!=='pendientes'||balance(p)>0),p=>p.id+' '+p.supplier+' '+p.invoice).map(p=>`<tr><td><strong>${p.id}</strong><small>${esc(p.invoice)}</small></td><td>${esc(p.supplier)}</td><td>${esc(p.product)}<small>${Number(p.qty).toLocaleString('es-CO',{maximumFractionDigits:3})} ${p.measureType==='Pesaje'?'g':'un.'}</small></td><td class="num">${money(p.total)}</td><td class="num">${money(balance(p))}</td><td>${fmtDate(p.dueDate)} ${balance(p)>0?badge(p.dueDate<appState.today?'Vencido':'Pendiente',p.dueDate<appState.today?'red':'warn'):badge('Pagado')}</td><td>${balance(p)>0&&allowed('compras','crear')?button('Abonar','purchase-payment-'+p.id,'text'):button('Detalle','purchase-'+p.id,'text')}</td></tr>`));}
function purchaseForm(){if(!data().suppliers.length){toast('Registra primero un proveedor.');appState.tab='proveedores';render();return contactForm('supplier');}if(!data().products.length){toast('Registra primero un producto en inventario.');return productForm();}modal('Registrar ingreso de mercancía',`<form id="purchase-form">${select('Proveedor','supplierId',data().suppliers.filter(s=>s.active!==false).map(s=>[s.id,s.name]))}${input('Número de factura del proveedor','invoice','','text','required')}${select('Producto','productId',data().products.filter(p=>p.active).map(p=>[p.id,p.sku+' · '+p.name+' · '+(p.measureType==='Pesaje'?'gramos':'unidades')]))}${input('Cantidad recibida (unidad del producto)','qty',1,'number','required min=".001" step=".001"')}${input('Costo total del ingreso (COP)','total','','number','required min="1" step="1"')}${input('Vencimiento','dueDate',appState.today,'date','required')}${input('Pago inicial (COP; 0 para crédito)','initial',0,'number','required min="0" step="1"')}${paymentFields()}<div class="info-strip">El ingreso incrementa el stock y recalcula su costo promedio ponderado. El pago reduce caja/cuenta y la deuda, sin contarse como gasto operativo.</div>${submit('Registrar compra')}</form>`);}
function paymentFields(){return select('Medio de pago','method',[['cash','Efectivo'],['transfer','Transferencia'],['card','Tarjeta']])+select('Cuenta para tarjeta / transferencia','accountId',data().accounts.filter(a=>a.active!==false).map(a=>[a.id,a.name]))+input('Referencia del pago (opcional)','reference');}
function abono(kind,id){const obj=(kind==='sale'?data().sales:data().purchases).find(x=>x.id===id);modal('Registrar abono · '+id,`<form id="payment-form" data-kind="${kind}" data-id="${id}"><p style="margin-bottom:20px">${esc(obj.customer||obj.supplier)} · Saldo ${money(balance(obj))}</p>${input('Valor del abono (COP)','amount','','number',`required min="1" max="${balance(obj)}" step="1"`)}${paymentFields()}${submit('Registrar abono')}</form>`);}
function cashView(){const shift=activeShift();return heading('Tu caja, bajo control.',shift?'Turno abierto por '+shift.openedBy+' · '+fmtDate(shift.openedAt)+' '+fmtTime(shift.openedAt):'No hay un turno abierto.',allowed('caja','crear')?button(shift?'Cerrar turno':'Abrir turno',shift?'shift-close':'shift-open','primary',shift?'lock':'wallet'):'')+(shift?`<div class="kpis">${kpi('Efectivo esperado',money(expected(shift)),'Base + entradas − salidas',true)}${kpi('Base inicial',money(shift.opening))}${kpi('Entradas en efectivo',money(data().movements.filter(m=>m.shiftId===shift.id&&m.accountId==='cash'&&m.amount>0).reduce((n,m)=>n+m.amount,0)))}${kpi('Salidas en efectivo',money(-data().movements.filter(m=>m.shiftId===shift.id&&m.accountId==='cash'&&m.amount<0).reduce((n,m)=>n+m.amount,0)))}</div>`:'')+tabs([['movimientos','Movimientos'],['cuentas','Cuentas bancarias'],['cierres','Historial de cierres']])+(appState.tab==='cuentas'?`<div class="grid-equal">${data().accounts.map(a=>`<article class="card account"><h2>${esc(a.name)}</h2><small>Saldo inicial + movimientos registrados</small><strong>${money(bank(a))}</strong></article>`).join('')}</div><div class="row">${allowed('caja','editar')?button('Transferir entre cuentas','transfer','','arrow'):''}${allowed('config','editar')?button('Nueva cuenta','account-new','','plus'):''}</div>`:appState.tab==='cierres'?`<section class="card">${table(['Apertura','Responsable','Esperado','Contado','Diferencia'],data().shifts.filter(s=>s.closedAt).slice().reverse().map(s=>`<tr><td>${fmtDate(s.openedAt)}</td><td>${esc(s.closedBy)}</td><td>${money(s.expected)}</td><td>${money(s.counted)}</td><td>${badge(s.difference===0?'Sin diferencia':(s.difference>0?'Sobrante ':'Faltante ')+money(Math.abs(s.difference)),s.difference?'warn':'')}</td></tr>`))}</section>`:`<section class="card"><div class="card-head"><h2>Movimientos ${shift?'del turno':'registrados'}</h2>${allowed('caja','crear')?button('Registrar movimiento','movement-new','','plus'):''}</div>${table(['Fecha / Hora','Concepto','Cuenta','Monto','Responsable'],data().movements.filter(m=>!shift||m.shiftId===shift.id).slice().reverse().map(m=>`<tr><td>${fmtDate(m.createdAt)}<small>${fmtTime(m.createdAt)}</small></td><td>${esc(m.description)}<small>${esc(kindLabels[m.kind]||m.kind)} · ${esc(m.ref)}</small></td><td>${m.accountId==='cash'?'Efectivo':esc(data().accounts.find(a=>a.id===m.accountId)?.name||'Cuenta')}</td><td class="num ${m.amount<0?'negative':''}">${m.amount<0?'− ':''}${money(Math.abs(m.amount))}</td><td>${esc(m.userName)}</td></tr>`))}</section>`);}
const kindLabels={sale:'Pago de venta',customer_payment:'Abono de cliente',purchase_payment:'Pago a proveedor',income:'Otro ingreso',expense:'Gasto operativo',adjustment:'Ajuste',transfer:'Transferencia interna',refund:'Devolución por anulación'};
function reportsView(){const r=reportLocal(appState.start,appState.end);const receivables=data().sales.filter(s=>s.mode==='credit').reduce((n,s)=>n+balance(s),0),deposits=data().sales.filter(s=>s.mode==='layaway'&&!s.recognizedAt&&!s.voidedAt).reduce((n,s)=>n+paid(s),0),payables=data().purchases.reduce((n,p)=>n+balance(p),0),reserved=data().sales.filter(s=>s.mode==='layaway'&&!s.recognizedAt&&!s.voidedAt).reduce((n,s)=>n+s.cost,0),inv=data().products.reduce((n,p)=>n+p.stock*p.cost,0)+reserved,cash=activeShift()?expected(activeShift()):data().shifts.at(-1)?.counted||0,available=cash+data().accounts.reduce((n,a)=>n+bank(a),0),assets=inv+available+receivables+data().assets.filter(a=>!a.archivedAt).reduce((n,a)=>n+a.value,0);return heading('Mira más allá de la venta.','Resultados desde las operaciones registradas. COP · Zona horaria de Bogotá.',exportButtons('reportes'))+`<div class="row report-filters">${input('Desde','report-start',appState.start,'date','required')}${input('Hasta','report-end',appState.end,'date','required')}${button('Aplicar periodo','apply-period','','check')}</div><div class="kpis">${kpi('Ventas reconocidas',money(r.net),r.count+' ventas',true)}${kpi('Costo de ventas',money(r.cost),'Costo histórico de cada línea')}${kpi('Utilidad bruta',money(r.gross),r.gross===null?'Sin costo histórico documentado':r.net?(r.gross/r.net*100).toFixed(1)+' % de margen':'Sin ventas en el periodo')}${kpi('Resultado operativo',money(r.profit),'Utilidad bruta − gastos')}</div><div class="grid-equal"><section class="card"><div class="card-head"><h2>Estado de resultados</h2></div>${table(['Concepto','Valor'],[['Ventas reconocidas',r.net],['Costo de ventas',r.cost],['Utilidad bruta',r.gross],['Gastos operativos',r.expenses],['Resultado operativo',r.profit]].map(([l,v])=>`<tr><td>${l}</td><td class="num">${money(v)}</td></tr>`))}</section><section class="card"><div class="card-head"><h2>Balance operativo actual</h2></div>${table(['Rubro','Valor'],[['Inventario (incluye separes reservados)',inv],['Caja y bancos',available],['Créditos de clientes',receivables],['Activos fijos registrados',data().assets.reduce((n,a)=>n+a.value,0)],['Total de activos',assets],['Deuda con proveedores',payables],['Anticipos de separes',deposits],['Patrimonio operativo',assets-payables-deposits]].map(([l,v])=>`<tr><td>${l}</td><td class="num">${money(v)}</td></tr>`))}</section></div><div class="info-strip">Los planes separe se reconocen como venta y costo al entregar la pieza. Antes de la entrega, sus abonos son anticipos. El balance es actual; no es un balance histórico al cierre del periodo seleccionado.</div>`;}
function settingsView(){const s=data().settings;return heading('Tu negocio, con tu identidad.','Una sola joyería. Ajustes generales y documentos comerciales.',button('Activos fijos','goto-activos','','box'))+`<section class="card settings-import" aria-label="Importación de Charles"><div class="card-head"><h2>Importar base de datos de Charles</h2></div><div class="card-body"><p>Trae el catálogo, los contactos, los activos y los saldos iniciales desde MongoDB o una copia JSON. Revisa los datos antes de confirmar. El historial antiguo se conserva para consulta.</p>${isSuper()?'<a class="btn primary" href="#importar">'+icon('download')+'Abrir importación de Charles</a>':'<p class="muted">Acceso exclusivo del superadministrador. Inicia sesión con esa cuenta para importar.</p>'}</div></section><div class="grid-equal"><section class="card"><div class="card-head"><h2>Información del negocio</h2></div><form class="card-body" id="settings-form">${input('Nombre comercial','name',s.name,'text','required')}${input('Razón social','legalName',s.legalName)}${input('NIT','taxId',s.taxId)}${input('Dirección','address',s.address)}${input('Teléfono','phone',s.phone)}${select('Papel térmico por defecto','receiptWidth',[[80,'80 mm'],[58,'58 mm']],s.receiptWidth)}${allowed('config','editar')?submit('Guardar configuración'):''}</form></section><section class="card" style="align-self:start"><div class="card-head"><h2>Categorías del catálogo</h2></div><div class="card-body"><div class="row">${data().categories.map(c=>badge(c)).join('')}</div>${allowed('inventario','crear')?`<form id="category-form" style="margin-top:24px">${input('Nueva categoría','name','','text','required maxlength="80"')}${submit('Añadir categoría')}</form>`:''}<div class="info-strip" style="margin-top:24px">Los respaldos se generan en el servidor con <code>npm run backup</code>. Guarda una copia fuera del equipo y prueba la restauración antes de usar datos reales.</div></div></section></div>`;}
function usersView(){return heading('El acceso correcto para cada persona.','Los permisos se verifican en el servidor en cada operación.',allowed('usuarios','crear')?button('Crear usuario','user-new','primary','plus'):'')+`<section class="card">${table(['Usuario','Correo','Rol','Estado',''],appState.users.map(u=>`<tr><td><strong>${esc(u.name)}</strong></td><td>${esc(u.email)}</td><td>${esc(u.role)}</td><td>${badge(u.active?'Activo':'Inactivo',u.active?'':'warn')}</td><td>${allowed('usuarios','editar')?button('Permisos y acceso','user-'+u.id,'text'):''}</td></tr>`))}</section><section class="card" style="margin-top:24px"><div class="card-head"><h2>Registro de auditoría</h2>${button('Consultar últimos cambios','audit','','receipt')}</div><div id="audit-results" class="card-body"><p class="muted">Consulta responsable, operación y fecha de los cambios registrados.</p></div></section>`;}
function userForm(id){const u=id?appState.users.find(u=>u.id===id):null;const modules=accessModules;modal(u?'Permisos de '+u.name:'Crear usuario',`<form id="user-form" data-id="${u?.id||''}">${input('Nombre','name',u?.name||'','text','required')}${u?'':input('Correo','email','','email','required')}${select('Rol','role',data().roles.filter(r=>isSuper()||r.name!=='Superadministrador').map(r=>r.name).concat('Personalizado'),u?.role||'Vendedor')}${input(u?'Nueva contraseña (deja vacío para conservar)':'Contraseña inicial','password','','password',`${u?'':'required'} minlength="12" autocomplete="new-password"`)}${u?select('Estado','active',[[1,'Activo'],[0,'Inactivo']],u.active?1:0):''}${true?`<details><summary style="cursor:pointer;padding:12px 0">Permisos personalizados por módulo</summary><div class="table-wrap"><table class="permission-table"><thead><tr><th>Módulo</th>${['Ver','Crear','Editar','Eliminar','Exportar'].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${modules.map(m=>`<tr><td>${labels[m]}</td>${['ver','crear','editar','eliminar','exportar'].map(a=>`<td><label class="check-target"><input class="permission" type="checkbox" name="perm-${m}-${a}" data-module="${m}" data-perm="${a}" ${(u?.permissions?.[m]??u?.permissions?.[accessParents[m]]??[]).includes(a)?'checked':''} aria-label="${a} ${labels[m]}"></label></td>`).join('')}</tr>`).join('')}</tbody></table></div><label class="row" style="margin:18px 0"><input type="checkbox" name="customPermissions" ${u?.customPermissions?'checked':''}> Aplicar esta matriz personalizada</label></details>`:''}<p class="muted" style="margin-bottom:16px">No se puede desactivar al último administrador. Cambiar la contraseña cierra las sesiones del usuario.</p>${submit('Guardar usuario')}</form>`);}
function servicesView(){return heading('El cuidado continúa en el taller.','Trabajos, estado y fecha comprometida. Presupuestos; no generan ventas automáticamente.',allowed('servicios','crear')?button('Nuevo servicio','service-new','primary','plus'):'')+`<section class="card">${table(['Trabajo','Cliente','Estado','Entrega','Precio',''],data().services.filter(s=>!s.archivedAt).map(s=>`<tr><td>${esc(s.name)}</td><td>${esc(s.customer)}</td><td>${badge(s.status,s.status==='Entregado'?'':'info')}</td><td>${fmtDate(s.dueDate)}</td><td class="num">${money(s.price)}</td><td>${allowed('servicios','editar')?button('Editar','service-'+s.id,'text'):''}</td></tr>`))}</section>`;}
function assetsView(){return heading('Las herramientas que sostienen tu negocio.','Registro de activos al valor indicado. No aplica depreciación ni registra pagos automáticamente.',allowed('activos','crear')?button('Nuevo activo','asset-new','primary','plus'):'')+`<section class="card">${table(['Activo','Valor actual',''],data().assets.filter(a=>!a.archivedAt).map(a=>`<tr><td>${esc(a.name)}</td><td class="num">${money(a.value)}</td><td>${allowed('activos','editar')?button('Editar','asset-'+a.id,'text'):''}</td></tr>`))}</section>`;}
function aiView(){return heading('Una nueva perspectiva de tu negocio.','Consulta tus cifras y prepara mensajes de cobranza para revisarlos antes de enviar.')+`<div class="chat-layout"><section class="card"><div class="card-head"><h2>${icon('spark',18)} Asistente Áurea</h2></div><div class="chat-thread" id="chat-thread"><div class="message"><small>ÁUREA</small>Consulta tus resultados. Sin clave de DeepSeek, recibirás un resumen calculado por el servidor.</div></div><form id="chat-form" class="chat-input"><input class="input" name="prompt" placeholder="¿Cómo va mi negocio?" aria-label="Consulta al asistente" required maxlength="2000"><button type="submit" class="btn primary" aria-label="Enviar consulta">${icon('arrow')}</button></form></section><section class="card" style="align-self:start"><div class="card-head"><h2>Un recordatorio a tiempo</h2></div><form class="card-body" id="collection-form">${select('Operación con saldo','saleId',data().sales.filter(s=>balance(s)>0).map(s=>[s.id,s.id+' · '+s.customer+' · '+money(balance(s))]))}${select('Tono','tone',['Cordial','Firme','Recordatorio'])}${submit('Preparar mensaje')}<label class="field" style="margin-top:20px"><span>Mensaje editable</span><textarea id="collection-message" rows="7"></textarea></label><div class="row">${button('Copiar','copy-message','','receipt')}${button('Abrir WhatsApp','whatsapp','','arrow')}</div><small style="display:block;margin-top:14px">El mensaje no se envía automáticamente. Revisa el cliente y el saldo antes de continuar en WhatsApp.</small></form></section></div>`;}
function saleDetail(id){const s=data().sales.find(s=>s.id===id);appState.lastSaleId=id;modal('Venta '+id,`<div class="row between"><strong>${esc(s.customer)}</strong>${saleStatus(s)}</div><p style="margin:14px 0">${fmtDate(s.createdAt)} · ${esc(s.cashier)}</p>${table(['Pieza','Cantidad','Total'],s.items.map(i=>`<tr><td>${esc(i.name)}<small>${esc(i.sku)}</small></td><td>${Number(i.qty).toLocaleString('es-CO',{maximumFractionDigits:3})} ${i.measureType==='Pesaje'?'g':'un.'}</td><td class="num">${money(i.lineTotal)}</td></tr>`))}<div class="payment-result">Total: ${money(s.total)} · Pagado: ${money(paid(s))} · Saldo: ${money(balance(s))}</div><h3 style="margin:20px 0">Pagos y abonos</h3>${table(['Fecha','Medio','Valor'],s.payments.map(p=>`<tr><td>${fmtDate(p.createdAt)}</td><td>${esc(p.methodName||paymentNames[p.method])}</td><td class="num">${money(p.amount)}</td></tr>`))}`,button('Comprobante','receipt-'+id,'','receipt')+(balance(s)>0&&allowed('clientes','crear')?button('Registrar abono','sale-payment-'+id,'primary','plus'):'')+(s.mode==='layaway'&&!s.voidedAt&&!s.recognizedAt&&balance(s)===0&&allowed('ventas','crear')?button('Entregar pieza','deliver-'+id,'primary','check'):'')+(!s.voidedAt&&allowed('ventas','eliminar')?button('Anular venta','void-'+id,'','close'):''));}
const paymentNames={cash:'Efectivo',card:'Tarjeta',transfer:'Transferencia'};
function receiptView(){const s=data().sales.find(s=>s.id===appState.lastSaleId);if(!s)return heading('Comprobante de venta','Selecciona una venta para revisar o imprimir su comprobante.')+empty('Cada comprobante tiene una venta','Los documentos se generan desde operaciones guardadas.',button('Ver ventas','goto-ventas','primary'));const settings=data().settings;return heading('Un comprobante a la altura de la pieza.','Documento comercial · No es factura electrónica.',button('Ver ventas','goto-ventas','','back'))+`<div class="receipt-tools"><button class="chip ${appState.width===58?'active':''}" data-width="58">58 mm</button><button class="chip ${appState.width===80?'active':''}" data-width="80">80 mm</button>${button('Imprimir comprobante','print','','print')}</div><div class="receipt-workspace"><article class="receipt ${appState.width===58?'narrow':''}"><h2>${esc(settings.name)}</h2><p>${esc(settings.legalName)}<br>${settings.taxId?'NIT '+esc(settings.taxId)+'<br>':''}${esc(settings.address)}<br>${esc(settings.addressExtra||'')}<br>${esc(settings.phone)}</p><hr><div class="receipt-line"><span>Venta</span><strong>${s.id}</strong></div><div class="receipt-line"><span>Fecha</span><span>${fmtDate(s.createdAt)}</span></div><p style="text-align:left">Cliente: ${esc(s.customer)}<br>Documento: ${esc(s.customerDoc||'—')}<br>Atendió: ${esc(s.cashier)}</p><hr>${s.items.map(i=>`<div><strong>${esc(i.name)}</strong><div>${esc(i.metal||'')}</div><div class="receipt-line"><span>${Number(i.qty).toLocaleString('es-CO',{maximumFractionDigits:3})} ${i.measureType==='Pesaje'?'g':'un.'}${i.measureType==='Unidades'&&i.weight?' · '+grams(i.weight)+'/un.':''}</span><span>${money(i.lineTotal)}</span></div>${i.discount?'<div>Descuento: '+money(i.discount)+'</div>':''}</div>`).join('<br>')}<hr><div class="receipt-line receipt-total"><span>TOTAL COP</span><span>${money(s.total)}</span></div><div class="receipt-line"><span>Pagado</span><span>${money(paid(s))}</span></div><div class="receipt-line"><span>Saldo</span><span>${money(balance(s))}</span></div><div class="receipt-line"><span>Efectivo recibido</span><span>${money(s.cashReceived||0)}</span></div><div class="receipt-line"><span>Cambio</span><span>${money(s.change||0)}</span></div><div>${saleStatus(s)}</div><hr>${s.payments.map(p=>`<div class="receipt-line"><span>${paymentNames[p.method]}</span><span>${money(p.amount)}</span></div>${p.accountName&&p.method!=='cash'?'<div>'+esc(p.accountName)+'</div>':''}${p.reference?'<div>Ref: '+esc(p.reference)+'</div>':''}`).join('')}<hr><p>Gracias por elegirnos.<br>COMPROBANTE COMERCIAL<br>NO ES FACTURA ELECTRÓNICA</p></article></div>`;}
function checkout(){syncCartFields();if(!activeShift())return toast('Abre un turno de caja antes de vender.');if(!appState.cart.length)return;if(cartTotal()<=0)return toast('Define un precio de venta antes de cobrar.');appState.payment='cash';appState.paymentMethodId='cash';paymentModal();}
function paymentModal(){modal('Completar venta',`<small>TOTAL A REGISTRAR · COP</small><div class="payment-total">${money(cartTotal())}</div><div class="payment-grid">${[['cash','Efectivo'],['card','Tarjeta'],['transfer','Transferencia'],['credit','Crédito'],['layaway','Plan separe'],['mixed','Pago mixto']].map(([id,label])=>`<button class="chip ${appState.payment===id?'active':''}" data-payment="${id}">${label}</button>`).join('')}</div><form id="checkout-form">${select('Cliente','customerId',[['','Cliente de mostrador'],...data().customers.map(c=>[c.id,c.name])],appState.customerId)}${appState.payment==='cash'?input('Efectivo recibido (COP)','received',cartTotal(),'number','required min="0" step="1"')+`<div class="payment-result" id="change-preview">Cambio: ${money(0)}</div>`:appState.payment==='mixed'?select('Primer medio','method1',[['cash','Efectivo'],['card','Tarjeta'],['transfer','Transferencia']],'cash')+input('Primer importe (COP)','cash',Math.round(cartTotal()/2),'number','required min="1" step="1"')+select('Cuenta del primer medio (si aplica)','account1',data().accounts.map(a=>[a.id,a.name]))+select('Segundo medio','method2',[['cash','Efectivo'],['card','Tarjeta'],['transfer','Transferencia']],'transfer')+input('Segundo importe (COP)','bank',cartTotal()-Math.round(cartTotal()/2),'number','required min="1" step="1"')+select('Cuenta del segundo medio (si aplica)','account2',data().accounts.map(a=>[a.id,a.name]))+input('Efectivo recibido (opcional; vacío = importe exacto)','received','','number','min="0" step="1"'):['credit','layaway'].includes(appState.payment)?input('Abono inicial (COP)','initial',0,'number','required min="0" step="1"')+input('Fecha de vencimiento / compromiso','dueDate',appState.today,'date','required')+paymentFields():select('Cuenta de destino','accountId',data().accounts.map(a=>[a.id,a.name]))+input('Referencia del pago','reference')}<div class="info-strip">Verifica productos, cliente y pago. Se guardarán la venta, existencias, movimiento de dinero y saldo en una sola transacción.</div>${submit('Confirmar y registrar venta')}</form>`);}
function exportButtons(module){return allowed(module,'exportar')?button('Exportar CSV','export-csv-'+module,'','download')+button('Excel (.xls)','export-xls-'+module,'','download'):'';}
let lastRenderedRoute=null;
function render(){if(!appState.user)return authView();if(!data())return;const route=appState.route;if(route==='login'){appState.route=allowed('inicio')?'inicio':'pos';}if(!allowed(appState.route)){const next=Object.keys(labels).find(r=>allowed(r));if(!next){document.querySelector('#app').innerHTML='<main class=empty><h1>Tu cuenta aún no tiene módulos asignados.</h1><p>Solicita permisos a la persona administradora.</p>'+button('Cerrar sesión','logout')+'</main>';return;}appState.route=next;}const sidebarScroll=document.querySelector('.sidebar nav')?.scrollTop||0;document.querySelector('#app').innerHTML=shell();const views={inicio:home,pos,ventas:salesView,inventario:productsView,producto:productView,metales:metalView,compras:purchasesView,clientes:clientView,caja:cashView,reportes:reportsView,usuarios:usersView,ia:aiView,config:settingsView,servicios:servicesView,activos:assetsView,comprobante:receiptView};const main=document.querySelector('#main');Object.assign(views,extraUI.views);main.innerHTML=(views[appState.route]||home)();extraUI.decorate?.();syncSidebar();if(lastRenderedRoute!==appState.route)main.classList.add('page-enter');lastRenderedRoute=appState.route;const sidebarNav=document.querySelector('.sidebar nav');if(sidebarNav)sidebarNav.scrollTop=sidebarScroll;document.title='Áurea · '+labels[appState.route];}
function formValue(form){const values=Object.fromEntries(new FormData(form));for(const key of ['stock','weight','price','cost','labor','minStock','creditLimit','opening','amount','rate','delta','qty','total','initial','counted','value'])if(values[key]!==undefined)values[key]=Number(values[key]);return values;}
function paymentFrom(v,value){return value>0?[{method:v.method||'cash',amount:value,accountId:(v.method||'cash')==='cash'?'cash':v.accountId,reference:v.reference||''}]:[];}
document.addEventListener('click',async e=>{const t=e.target.closest('[data-action],[data-add],[data-remove],[data-category],[data-tab],[data-payment],[data-width]');if(!t)return;try{
if(t.dataset.add){const p=data().products.find(p=>p.id===t.dataset.add);const row=appState.cart.find(i=>i.productId===p.id);const add=p.measureType==='Pesaje'?Math.min(1,p.stock):1;if(row){if(row.qty+add>p.stock)return toast('No hay más existencias disponibles.');row.qty=Math.round((row.qty+add)*1000)/1000;}else appState.cart.push({productId:p.id,qty:add,unitPrice:p.price,discount:0});document.querySelector('#cart').innerHTML=cartView();document.querySelector('.pos-cart-shortcut').textContent='Ver carrito · '+money(cartTotal());return toast('Pieza agregada a la venta.');}
if(t.dataset.remove!==undefined){appState.cart.splice(Number(t.dataset.remove),1);render();return;}
if(t.dataset.category){appState.category=t.dataset.category;render();return;}
if(t.dataset.tab){appState.tab=t.dataset.tab;appState.query='';render();return;}
if(t.dataset.payment){appState.paymentMethodId=t.dataset.payment;appState.payment=t.dataset.payment;paymentModal();return;}
if(t.dataset.width){appState.width=Number(t.dataset.width);render();return;}
const a=t.dataset.action;if(!a||a==='none')return;if(a.startsWith('x-')){await extraUI.action?.(a,t);return;}
if(a.startsWith('goto-')){closeModal();go(a.slice(5));return;}
if(a.startsWith('product-edit-'))return productForm(a.slice(13));if(a==='product-new')return productForm();if(a.startsWith('product-')){selectedProductId=a.slice(8);go('producto');return;}
if(a.startsWith('customer-edit-'))return contactForm('customer',a.slice(14));if(a==='customer-new')return contactForm('customer');if(a.startsWith('customer-'))return customerDetail(a.slice(9));
if(a.startsWith('supplier-edit-'))return contactForm('supplier',a.slice(14));if(a==='supplier-new')return contactForm('supplier');if(a.startsWith('supplier-')){const id=a.slice(9),s=data().suppliers.find(s=>s.id===id);return modal(s.name,table(['Orden','Factura','Saldo',''],data().purchases.filter(p=>p.supplierId===id).map(p=>`<tr><td>${p.id}</td><td>${esc(p.invoice)}</td><td>${money(balance(p))}</td><td>${balance(p)&&allowed('compras','crear')?button('Abonar','purchase-payment-'+p.id,'text'):''}</td></tr>`)));}
if(a.startsWith('sale-payment-'))return abono('sale',a.slice(13));if(a.startsWith('purchase-payment-'))return abono('purchase',a.slice(17));if(a==='purchase-new')return purchaseForm();if(a.startsWith('purchase-')){const p=data().purchases.find(p=>p.id===a.slice(9));return modal(p.id,`<p>${esc(p.supplier)} · Factura ${esc(p.invoice)}</p><p>Total ${money(p.total)} · Saldo ${money(balance(p))}</p>`);}
if(a.startsWith('sale-'))return saleDetail(a.slice(5));if(a.startsWith('receipt-')){appState.lastSaleId=a.slice(8);appState.width=data().settings.receiptWidth;closeModal();go('comprobante');return;}
if(a.startsWith('metal-')){const m=data().metals.find(m=>m.id===a.slice(6));return modal('Actualizar '+m.name,`<form id="metal-form" data-id="${m.id}">${input('Tarifa comercial (COP/g)','rate',m.rate,'number','required min="1" step="1"')}${submit('Confirmar nueva tarifa')}</form>`);}
if(a.startsWith('stock-'))return modal('Ajustar existencias',`<form id="stock-form" data-id="${a.slice(6)}">${input('Variación (positiva o negativa)','delta','','number','required step=".001"')}${input('Motivo obligatorio','reason','','text','required')}${submit('Guardar ajuste')}</form>`);
if(a.startsWith('archive-'))return modal('Desactivar referencia',`<form id="archive-form" data-id="${a.slice(8)}"><p style="margin-bottom:20px">La referencia dejará de aparecer en el catálogo. Su historial se conserva. Se requiere stock cero.</p>${submit('Confirmar desactivación')}</form>`);
if(a.startsWith('void-'))return modal('Anular '+a.slice(5),`<form id="void-form" data-id="${a.slice(5)}"><div class="info-strip">Se repondrá el stock y se registrará la devolución de todos los pagos a sus cuentas originales. Esta acción queda auditada.</div>${input('Motivo de anulación','reason','','text','required')}${submit('Confirmar anulación y devolución')}</form>`);
if(a.startsWith('deliver-'))return modal('Entregar plan separe',`<form id="deliver-form" data-id="${a.slice(8)}"><p style="margin-bottom:20px">Confirma que entregas la pieza al cliente. Se reconocerán la venta y su costo; el plan debe estar pagado.</p>${submit('Confirmar entrega')}</form>`);
if(a==='user-new')return userForm();if(a.startsWith('user-'))return userForm(a.slice(5));
if(a==='service-new'||a.startsWith('service-')){const s=a==='service-new'?null:data().services.find(s=>s.id===a.slice(8));return modal(s?'Editar servicio':'Nuevo servicio',`<form id="service-form" data-id="${s?.id||''}">${input('Trabajo / descripción','name',s?.name||'','text','required')}${input('Cliente','customer',s?.customer||'','text','required')}${input('Presupuesto (COP)','price',s?.price||0,'number','required min="0" step="1"')}${input('Costo previsto (COP)','cost',s?.cost||0,'number','required min="0" step="1"')}${input('Fecha de entrega','dueDate',s?.dueDate||appState.today,'date','required')}${select('Estado','status',['Recibido','En proceso','Listo','Entregado'],s?.status||'Recibido')}${submit('Guardar servicio')}</form>`);}
if(a==='asset-new'||a.startsWith('asset-')){const x=a==='asset-new'?null:data().assets.find(x=>x.id===a.slice(6));return modal('Registrar activo fijo',`<form id="asset-form" data-id="${x?.id||''}">${input('Nombre del activo','name',x?.name||'','text','required')}${input('Valor actual (COP)','value',x?.value||0,'number','required min="0" step="1"')}${submit('Guardar activo')}</form>`);}
if(a.startsWith('export-')){const [,format,module]=a.split('-');return downloadExport(module,format);}
switch(a){case'menu':toggleSidebar();break;case'close-dialog':closeModal();break;case'checkout':checkout();break;case'review-cart':await load();appState.cart.forEach(i=>{const p=data().products.find(p=>p.id===i.productId);if(p&&!i.manualPrice)i.unitPrice=p.price;});closeModal();render();toast('Referencias actualizadas. Revisa cantidades, precios y total antes de continuar.');break;case'scroll-cart':document.querySelector('#cart').scrollIntoView({behavior:'smooth'});break;
case'account':modal('Tu espacio de trabajo',`<p>${esc(appState.user.name)} · ${esc(appState.user.email)}</p><p class="muted">${esc(appState.user.role)} · Sesión protegida</p>`,button('Actualizar datos','refresh','','check')+button('Cambiar contraseña','password','','lock')+button('Cerrar sesión','logout','','logout'));break;
case'refresh':await load();closeModal();render();toast('Datos actualizados.');break;
case'password':modal('Cambiar mi contraseña',`<form id="password-form">${input('Contraseña actual','currentPassword','','password','required autocomplete="current-password"')}${input('Nueva contraseña','newPassword','','password','required minlength="12" autocomplete="new-password"')}${submit('Cambiar contraseña y cerrar sesiones')}</form>`);break;
case'logout':await api('/api/logout',{method:'POST',body:'{}'});appState.user=null;appState.csrf=null;appState.data=null;appState.cart=[];closeModal();authView();break;
case'notifications':modal('Requieren tu atención',`<p>${data().products.filter(p=>p.active&&p.stock<=p.minStock).length} referencias con existencias bajas.</p><p>${data().sales.filter(s=>balance(s)>0&&s.dueDate<appState.today).length} obligaciones de clientes vencidas.</p><p>${data().purchases.filter(p=>balance(p)>0&&p.dueDate<appState.today).length} compras vencidas pendientes de pago.</p>`);break;
case'shift-open':modal('Abrir turno de caja',`<form id="open-form">${input('Efectivo inicial contado (COP)','opening',0,'number','required min="0" step="1"')}${submit('Abrir turno')}</form>`);break;
case'shift-close':modal('Conteo de cierre',`<form id="close-form" data-id="${activeShift().id}"><p style="margin-bottom:20px">Cuenta el efectivo físico. La comparación se mostrará al revisar el cierre.</p>${input('Efectivo contado (COP)','counted','','number','required min="0" step="1"')}${input('Observación (obligatoria con diferencia)','note')}${submit('Revisar cierre')}</form>`);break;
case'movement-new':modal('Registrar movimiento',`<form id="movement-form">${select('Tipo de movimiento','kind',[['income','Otro ingreso (no venta)'],['expense','Gasto operativo']])}${select('Cuenta','accountId',[['cash','Caja en efectivo'],...data().accounts.map(a=>[a.id,a.name])])}${input('Concepto','description','','text','required')}${input('Monto (COP)','amount','','number','required min="1" step="1"')}${submit('Registrar movimiento')}</form>`);break;
case'account-new':modal('Registrar cuenta',`<form id="account-form">${input('Nombre','name','','text','required')}${input('Saldo inicial existente (COP)','opening',0,'number','required min="0" step="1"')}<p class="muted" style="margin-bottom:16px">El saldo inicial no se cuenta como ingreso ni venta.</p>${submit('Guardar cuenta')}</form>`);break;
case'transfer':modal('Transferir entre cuentas',`<form id="transfer-form">${select('Origen','from',[['cash','Caja en efectivo'],...data().accounts.map(a=>[a.id,a.name])])}${select('Destino','to',data().accounts.map(a=>[a.id,a.name]).concat([['cash','Caja en efectivo']]))}${input('Monto (COP)','amount','','number','required min="1" step="1"')}${input('Concepto','description','','text','required')}${submit('Confirmar transferencia registrada')}</form>`);break;
case'apply-period':{const start=document.querySelector('[name="report-start"]').value,end=document.querySelector('[name="report-end"]').value;if(!start||!end||start>end)return toast('Revisa las fechas del periodo.');appState.start=start;appState.end=end;render();break;}
case'audit':{const r=await api('/api/audit');document.querySelector('#audit-results').innerHTML=table(['Fecha','Operación','Responsable','Detalle'],r.entries.map(x=>`<tr><td>${fmtDate(x.createdAt)}<small>${fmtTime(x.createdAt)}</small></td><td>${esc(x.command)}</td><td>${esc(appState.users.find(u=>u.id===x.userId)?.name||'Instalación')}</td><td style="white-space:normal">${esc(x.summary)}</td></tr>`));break;}
case'print':{let style=document.querySelector('#print-size');if(!style){style=document.createElement('style');style.id='print-size';document.head.append(style);}style.textContent=`@media print{@page{size:${appState.width}mm auto}}`;window.print();break;}
case'copy-message':{const text=document.querySelector('#collection-message').value;if(!text)return toast('Primero prepara un mensaje.');try{await navigator.clipboard.writeText(text);toast('Mensaje copiado.');}catch{toast('Selecciona y copia el texto de la vista previa.');}break;}
case'whatsapp':{const message=document.querySelector('#collection-message').value;if(!message)return toast('Primero prepara el mensaje.');modal('Revisar antes de abrir WhatsApp',`<p style="white-space:pre-wrap">${esc(message)}</p><p class="muted" style="margin-top:16px">Elige el destinatario en WhatsApp. El envío lo confirmas allí.</p>`,`<a class="btn primary" target="_blank" rel="noopener noreferrer" href="https://wa.me/?text=${encodeURIComponent(message)}">Continuar a WhatsApp</a>`);break;}
}
}catch(error){toast(error.message);}});
document.addEventListener('submit',async e=>{const form=e.target;if(!(form instanceof HTMLFormElement))return;e.preventDefault();if(form.dataset.busy==='true')return;const v=formValue(form);const errorEl=form.querySelector('.form-error');if(errorEl)errorEl.textContent='';const buttons=[...form.querySelectorAll('button[type="submit"]')];form.dataset.busy='true';buttons.forEach(b=>b.disabled=true);let command=null,body=null,doneMessage='Cambios guardados.';try{
await extraUI.beforeSubmit?.(form,v);
switch(form.id){
case'setup-form':await api('/api/setup',{method:'POST',headers:v.setupToken?{'X-Setup-Token':v.setupToken}:{},body:JSON.stringify(v)});appState.initialized=true;await signIn(v);return;
case'login-form':await signIn(v);return;
case'password-form':await api('/api/password',{method:'POST',body:JSON.stringify(v)});appState.user=null;appState.csrf=null;appState.data=null;appState.cart=[];closeModal();authView();toast('Contraseña actualizada. Inicia sesión nuevamente.');return;
case'product-form':{if(v.pricing==='metal'){const m=data().metals.find(m=>m.name===v.metal);if(!m)throw Error('Selecciona un metal con tarifa disponible.');v.price=Math.round((v.measureType==='Pesaje'?1:v.weight)*m.rate+v.labor);}command='product.save';body={...v,id:form.dataset.id||undefined};break;}
case'contact-form':command='contact.save';body={...v,id:form.dataset.id||undefined,kind:form.dataset.kind};break;
case'metal-form':command='metal.update';body={id:form.dataset.id,rate:v.rate};break;
case'stock-form':command='product.adjust';body={id:form.dataset.id,delta:v.delta,reason:v.reason};break;
case'archive-form':command='product.archive';body={id:form.dataset.id};break;
case'open-form':command='shift.open';body=v;break;
case'close-form':{const shift=activeShift();if(!shift||shift.id!==form.dataset.id)throw Error('El turno cambió. Actualiza antes de continuar.');const diff=v.counted-expected(shift);if(diff&&!v.note.trim())throw Error('Explica la diferencia antes de confirmar el cierre.');if(form.dataset.confirmed!=='true'){let preview=form.querySelector('.close-preview');if(!preview){preview=document.createElement('div');preview.className='payment-result close-preview';form.querySelector('.form-error').before(preview);}preview.innerHTML=`Esperado: <strong>${money(expected(shift))}</strong><br>Contado: ${money(v.counted)}<br><strong>${diff===0?'Sin diferencia':(diff<0?'Faltante ':'Sobrante ')+money(Math.abs(diff))}</strong><br>Revisa y pulsa otra vez para cerrar el turno.`;form.dataset.confirmed='true';buttons[0].textContent='Confirmar cierre de turno';return;}command='shift.close';body={id:shift.id,...v};break;}
case'movement-form':command='movement.create';body=v;break;
case'account-form':command='account.save';body=v;break;
case'transfer-form':command='account.transfer';body=v;break;
case'settings-form':command='settings.save';body={...v,receiptWidth:Number(v.receiptWidth),taxRate:Number(v.taxRate||0)};break;
case'category-form':command='category.create';body=v;break;
case'purchase-form':command='purchase.create';body={...v,payments:paymentFrom(v,v.initial)};break;
case'payment-form':command=form.dataset.kind==='sale'?'sale.payment':'purchase.payment';body={id:form.dataset.id,payments:paymentFrom(v,v.amount)};break;
case'void-form':command='sale.void';body={id:form.dataset.id,reason:v.reason};break;
case'deliver-form':command='sale.deliver';body={id:form.dataset.id};break;
case'service-form':command='service.save';body={...v,id:form.dataset.id||undefined};break;
case'asset-form':command='asset.save';body={...v,id:form.dataset.id||undefined};break;
case'checkout-form':{const mode=['credit','layaway'].includes(appState.payment)?appState.payment:'paid';let payments=[];if(appState.payment==='cash'){if(Number(v.received)<cartTotal())throw Error('El efectivo recibido no cubre el total.');payments=[{method:'cash',amount:cartTotal()}];}else if(appState.payment==='mixed'){payments=[{method:v.method1,amount:Number(v.cash),accountId:v.method1==='cash'?'cash':v.account1},{method:v.method2,amount:Number(v.bank),accountId:v.method2==='cash'?'cash':v.account2}];}else if(mode!=='paid'){payments=paymentFrom(v,v.initial);}else payments=[{method:appState.payment,amount:cartTotal(),accountId:v.accountId,reference:v.reference||''}];payments.forEach(p=>{if(p.method==='card')p.feePercent=Number(v.cardFee||0);});command='sale.create';body={items:appState.cart,paymentMethodId:appState.paymentMethodId,customerId:v.customerId||null,mode,dueDate:v.dueDate,payments,cashReceived:v.received===undefined||v.received===''?undefined:Number(v.received)};doneMessage='Venta registrada. Existencias, pagos y saldo guardados.';break;}
case'user-form':{const body={...v,id:form.dataset.id||undefined};if(body.active!==undefined)body.active=body.active==='1';if(!body.password)delete body.password;body.useRolePermissions=!v.customPermissions;if(v.customPermissions){body.permissions={};for(const m of accessModules)body.permissions[m]=['ver','crear','editar','eliminar','exportar'].filter(a=>v['perm-'+m+'-'+a]);}await api(form.dataset.id?'/api/users/update':'/api/users',{method:'POST',body:JSON.stringify(body)});await load();const session=await api('/api/session');appState.user=session.user;appState.csrf=session.csrf;closeModal();render();toast('Usuario guardado.');return;}
case'collection-form':{const s=data().sales.find(s=>s.id===v.saleId);if(!s)throw Error('No hay una operación con saldo pendiente.');const intro=v.tone==='Cordial'?'Esperamos que estés muy bien.':v.tone==='Firme'?'Queremos acordar una fecha para tu próximo abono.':'Te compartimos un recordatorio de tu cuenta.';document.querySelector('#collection-message').value=`Hola, ${s.customer}. ${intro} Te saludamos de ${data().settings.name}. Tu operación ${s.id} tiene un saldo pendiente de ${money(balance(s))} COP, con fecha de compromiso ${fmtDate(s.dueDate)}. ¿Nos confirmas cuándo puedes realizar tu abono? Gracias por tu atención.`;return;}
case'chat-form':{const thread=document.querySelector('#chat-thread');thread.insertAdjacentHTML('beforeend',`<div class="message mine"><small>TÚ</small>${esc(v.prompt)}</div>`);const r=await api('/api/ai',{method:'POST',body:JSON.stringify({prompt:v.prompt})});thread.insertAdjacentHTML('beforeend',`<div class="message"><small>${r.local?'RESUMEN CALCULADO · SIN MODELO CONECTADO':'DEEPSEEK · REVISAR INTERPRETACIÓN'}</small>${esc(r.reply)}</div>`);thread.scrollTop=thread.scrollHeight;form.reset();return;}
default:{const extra=await extraUI.submit?.(form,v);if(!extra)return;command=extra.command;body=extra.body;break;}
}
if(command){const saved=await mutate(command,body,form);if(command==='sale.create'){appState.lastSaleId=saved.entityId;appState.cart=[];appState.customerId='';closeModal();go('comprobante');}else{closeModal();render();}toast(doneMessage);}
}catch(error){if(errorEl)errorEl.textContent=error.message;else toast(error.message);if(error.status===409){await load().catch(()=>{});form._request=null;if(form.id==='checkout-form'&&!form.querySelector('[data-action=review-cart]'))errorEl.insertAdjacentHTML('afterend',button('Revisar precios y existencias','review-cart','text'));if(form.id==='close-form'){form.dataset.confirmed='false';form.querySelector('.close-preview')?.remove();buttons[0].textContent='Revisar cierre';}} if(error.status===401){appState.user=null;closeModal();authView();}}finally{form.dataset.busy='false';buttons.forEach(b=>b.disabled=false);}});
async function signIn(v){const r=await api('/api/login',{method:'POST',body:JSON.stringify({email:v.email,password:v.password})});appState.user=r.user;appState.csrf=r.csrf;await load();appState.route=allowed('inicio')?'inicio':allowed('pos')?'pos':Object.keys(labels).find(x=>allowed(x))||'inicio';location.hash=appState.route;render();}
function updateResults(){const el=document.querySelector('#results');if(!el)return;el.innerHTML=appState.route==='inventario'?productRows():appState.route==='clientes'?customerRows():appState.route==='compras'?purchaseRows():salesTable(filtered(data().sales,s=>s.id+' '+s.customer+' '+s.date));}
function syncCartFields(){for(const field of document.querySelectorAll('[data-cart-qty]')){const row=appState.cart[Number(field.dataset.cartQty)],p=data().products.find(p=>p.id===row.productId),n=Number(field.value);if(!Number.isFinite(n)||n<=0||n>p.stock||(p.measureType==='Unidades'&&!Number.isInteger(n)))throw Error('Revisa cantidades y existencias del carrito.');row.qty=n;}for(const field of document.querySelectorAll('[data-unit-price]')){const row=appState.cart[Number(field.dataset.unitPrice)],n=Number(field.value);if(!Number.isFinite(n)||n<=0)throw Error('Revisa los precios del carrito.');if(row.unitPrice!==n){row.unitPrice=n;row.manualPrice=true;}}for(const field of document.querySelectorAll('[data-discount]')){const row=appState.cart[Number(field.dataset.discount)],n=Number(field.value);if(!Number.isSafeInteger(n)||n<0||n>=Math.round(row.qty*row.unitPrice))throw Error('Revisa los descuentos del carrito.');row.discount=n;}}
function refreshCartTotals(){document.querySelectorAll('.cart-item').forEach((el,i)=>{const strong=el.querySelector('.row strong');if(strong)strong.textContent=money(Math.round(appState.cart[i].qty*appState.cart[i].unitPrice)-appState.cart[i].discount);});const total=document.querySelector('.cart-summary .grand span:last-child');if(total)total.textContent=money(cartTotal());const weight=document.querySelector('.cart-summary .total-line:first-child span:last-child');if(weight)weight.textContent=grams(appState.cart.reduce((n,i)=>{const p=data().products.find(p=>p.id===i.productId);return n+i.qty*(p.measureType==='Pesaje'?1:p.weight);},0));const shortcut=document.querySelector('.pos-cart-shortcut');if(shortcut)shortcut.textContent='Ver carrito · '+money(cartTotal());}
document.addEventListener('input',e=>{if(e.target.matches('[data-cart-qty],[data-unit-price],[data-discount]')){try{syncCartFields();refreshCartTotals();}catch{}} if(e.target.id==='search'){appState.query=e.target.value;updateResults();}if(e.target.id==='pos-search')document.querySelector('#catalog').innerHTML=catalog(e.target.value);if(e.target.name==='received'){const preview=document.querySelector('#change-preview');if(preview)preview.textContent='Cambio: '+money(Math.max(0,Number(e.target.value)-cartTotal()));}if(e.target.closest('#close-form')){e.target.form.dataset.confirmed='false';e.target.form.querySelector('.close-preview')?.remove();e.target.form.querySelector('button[type=submit]').textContent='Revisar cierre';}});
document.addEventListener('change',e=>{const t=e.target;if(t.name==='cart-customer')appState.customerId=t.value;if(t.dataset.cartQty!==undefined){const row=appState.cart[Number(t.dataset.cartQty)],p=data().products.find(p=>p.id===row.productId);const n=Number(t.value);if(n<=0||n>p.stock||p.measureType==='Unidades'&&!Number.isInteger(n)){toast('Cantidad inválida o superior al stock.');}else row.qty=n;render();}if(t.dataset.unitPrice!==undefined){const row=appState.cart[Number(t.dataset.unitPrice)],n=Number(t.value);if(!Number.isFinite(n)||n<=0)toast('Precio inválido.');else{row.unitPrice=n;row.manualPrice=true;}render();}if(t.dataset.discount!==undefined){const row=appState.cart[Number(t.dataset.discount)];const n=Number(t.value);if(!Number.isInteger(n)||n<0||n>=Math.round(row.qty*row.unitPrice))toast('Descuento inválido.');else row.discount=n;render();}if(t.classList.contains('permission')){const others=[...document.querySelectorAll(`.permission[data-module="${t.dataset.module}"]`)];if(t.dataset.perm==='ver'&&!t.checked)others.forEach(x=>x.checked=false);else if(t.checked)others[0].checked=true;}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!sidebarDesktop.matches)toggleSidebar(false);if(e.key==='Enter'&&e.target.id==='pos-search'){e.preventDefault();const p=data().products.find(p=>[p.sku,p.barcode||''].some(code=>code.toLowerCase()===e.target.value.trim().toLowerCase()));if(p)document.querySelector(`[data-add="${p.id}"]`)?.click();}});
window.addEventListener('hashchange',()=>{const r=location.hash.slice(1);if(r==='main')return document.querySelector('#main')?.focus();appState.route=labels[r]?r:'inicio';appState.tab='';appState.query='';render();window.scrollTo(0,0);document.querySelector('#main')?.focus({preventScroll:true});});
async function downloadExport(module,format){const payload=await api(`/api/export?module=${module}&start=${appState.start}&end=${appState.end}`);const rows=[payload.headers,...payload.rows];let content,type,extension;const safe=v=>typeof v==='string'&&/^[=+\-@\t\r]/.test(v)?"'"+v:v;if(format==='xls'){const xml=v=>String(safe(v)).replace(/[<>&"']/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&apos;'}[c]));content='<?xml version="1.0"?><?mso-application progid="Excel.Sheet"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"><Worksheet ss:Name="Aurea"><Table>'+rows.map(row=>'<Row>'+row.map(v=>'<Cell><Data ss:Type="'+(typeof v==='number'?'Number':'String')+'">'+xml(v)+'</Data></Cell>').join('')+'</Row>').join('')+'</Table></Worksheet></Workbook>';type='application/vnd.ms-excel';extension='xls';}else{content='\ufeff'+rows.map(r=>r.map(v=>'"'+String(safe(v)).replace(/"/g,'""')+'"').join(';')).join('\r\n');type='text/csv;charset=utf-8';extension='csv';}const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download='Aurea-'+module+'-'+appState.today+'.'+extension;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('Exportación generada con los datos registrados.');}
async function boot(){document.querySelector('#app').innerHTML='<main class="empty"><h1>Estamos preparando tu espacio.</h1><p>Cargando Áurea…</p></main>';try{const r=await api('/api/session');appState.initialized=r.initialized;appState.user=r.user;appState.csrf=r.csrf;if(r.user){await load();const route=location.hash.slice(1);appState.route=labels[route]?route:allowed('inicio')?'inicio':'pos';render();}else authView();}catch(e){if(extraUI.offline?.(e))return;document.querySelector('#app').innerHTML=`<main class="empty"><h1>Áurea necesita su servidor.</h1><p>${esc(e.message)}</p><p>Desde la carpeta de Áurea ejecuta <code>npm start</code> y abre <a href="http://127.0.0.1:4178">http://127.0.0.1:4178</a>.</p></main>`;}}
if(document.readyState!=='complete')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
